function pingpong(x : integer) : integer;
var ping, pong, tenis, meja : integer;
begin
 meja := 0;
 for ping := 1 to x do begin
 for pong := 1 to ping do begin
 for tenis := ping downto pong do begin
 meja := meja + tenis;
 end;
 end;
 end;
 pingpong := tenis + meja;
end;

